const items = $input.all();

// Extract answers from Fillout Gmail "text" using a predefined ordered question list.

const QUESTIONS = [
  "First name",
  "Last name",
  "Email",

  "I will read, watch, and review all materials provided to me, ensuring I have the necessary knowledge to fully participate and move forward.",
  "I confirm that I will provide thorough, detailed responses that reflect my genuine understanding and commitment to this opportunity.",
  "I confirm that the information I provide is my own work and that I will not use AI tools to generate any responses on my behalf.",
  "I agree to share my authentic opinions and experiences, offering genuine feedback without embellishment or misrepresentation.",
  "I understand that this indicates my commitment to these statements, and I acknowledge that failing to adhere may jeopardize my participation in this opportunity.",
  "Please note: John Hazlewood, Founder and CEO of FloLabs, will personally review your response prior to your one-on-one meeting with him. Please ensure your answers reflect your genuine reply.",

  "After comparing the second meeting recording to the first one with Admiral Inman, what progress or new directions stood out to you the most?",
  "Can you please provide your thoughts and feedback on the article? (1)",
  "How does it relate to our projects at FloLabs? (1)",

  "Can you please provide your thoughts and feedback on the podcast?",
  "How do the insights shared in the podcast relate to our projects at FloLabs?",

  "Can you please provide your thoughts and feedback on the video?",
  "How does it relate to our projects at FloLabs? (2)",

  "Can you please provide your thoughts and feedback on the article?",
  "How does it relate to our projects at FloLabs?",

  "What did you find the most interesting and the least interesting?",
  "Do you think any of the content in this form should be excluded?",
  "Can you put them in a logical sequence of how you think participants should review the content?",
  "Any other comment you think would be helpful.",

  "Reference 1",
  "Reference 2",
];

function normalize(s) {
  return (s || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n");
}

function normalizeLines(s) {
  return normalize(s)
    .split("\n")
    .map(l => l.trim())
    .filter(l => l.length > 0);
}

function stripAsterisk(q) {
  return (q || "").replace(/\s*\*+\s*$/g, "").trim();
}

function extractResponsesBlock(text) {
  const idx = text.indexOf("RESPONSES:");
  if (idx === -1) return text;
  return text.slice(idx + "RESPONSES:".length);
}

function isFooterLine(line) {
  return /^View (submission|all of your form's submissions)/i.test(line);
}

function parseWithAnchors(lines, questions) {
  const qNormToCanonical = new Map();

  for (const q of questions) {
    const qClean = stripAsterisk(q);
    const qNorm = qClean.toLowerCase();
    qNormToCanonical.set(qNorm, qClean);
  }

  const anchors = [];
  for (let i = 0; i < lines.length; i++) {
    const ln = stripAsterisk(lines[i]);
    const norm = ln.toLowerCase();

    if (qNormToCanonical.has(norm)) {
      anchors.push({ i, qNorm: norm });
    }
  }

  const fields = [];
  const map = {};

  for (let a = 0; a < anchors.length; a++) {
    const startIdx = anchors[a].i;
    const qNorm = anchors[a].qNorm;
    const q = qNormToCanonical.get(qNorm);

    const answerStart = startIdx + 1;
    const answerEnd = (a + 1 < anchors.length) ? anchors[a + 1].i : lines.length;

    const ansLines = [];
    for (let j = answerStart; j < answerEnd; j++) {
      const line = lines[j];
      if (isFooterLine(line)) break;
      if (/^RESPONSES:?$/i.test(line)) continue;
      ansLines.push(line);
    }

    const answer = ansLines.join("\n").trim();

    fields.push({
      question: q,
      answer
    });

    map[q] = answer;
  }

  return { fields, map };
}

return items.map(item => {
  const rawText = item.json.text || "";
  const block = extractResponsesBlock(normalize(rawText));
  const lines = normalizeLines(block);

  const form = parseWithAnchors(lines, QUESTIONS);

  item.json.formFields = form.fields;
  item.json.firstName = form.map["First name"] || null;
  item.json.lastName = form.map["Last name"] || null;
  item.json.email = form.map["Email"] || null;

  return item;
});

const ff = Array.isArray(item.json.formFields) ? item.json.formFields : [];

// Remove the first 9 consent/basic fields
const trimmed = ff.slice(9);

// Keep the cleaned list
item.json.formFields = trimmed;

// Build JSON string for AI node
item.json.qa_json = JSON.stringify(
  trimmed.map(x => ({
    q: x.question || "",
    a: x.answer || ""
  }))
);

return item;

return $input.all().map(item => {
  let out = item.json.output;

  if (typeof out === 'string') {
    const s = out.trim();

    try {
      out = JSON.parse(s);
    } catch (e) {
      const m = s.match(/\{[\s\S]*\}/);
      if (m) {
        try {
          out = JSON.parse(m[0]);
        } catch (e2) {
          out = {
            fails: [{ question: '', answer: '', reason: 'unparseable_output' }],
            passCount: 0,
            failCount: 1
          };
        }
      } else {
        out = {
          fails: [{ question: '', answer: '', reason: 'unparseable_output' }],
          passCount: 0,
          failCount: 1
        };
      }
    }
  }

  const fails = Array.isArray(out.fails) ? out.fails : [];
  const failCount = Number.isFinite(out.failCount) ? out.failCount : fails.length;
  const passCount = Number.isFinite(out.passCount) ? out.passCount : 0;

  item.json.aiCheck = {
    fails,
    failCount,
    passCount
  };

  item.json.fails = fails;
  item.json.failCount = failCount;
  item.json.passCount = passCount;

  return item;
});
